class Solution:
    def maximizeTheProfit(self, n: int, offers: List[List[int]]) -> int:
        offers.sort(key=lambda o: o[1])
        dp = [0] * (n + 1)
        j = 0; m = len(offers)
        for i in range(1, n + 1):
            dp[i] = dp[i - 1]
            while j < m and offers[j][1] == i - 1:
                s, e, g = offers[j]
                dp[i] = max(dp[i], g + dp[s])
                j += 1
        return dp[n]

