class Solution {
public:
    int maximizeTheProfit(int n, vector<vector<int>>& offers) {
        sort(offers.begin(), offers.end(), [](auto& a, auto& b){ return a[1] < b[1]; });
        vector<int> dp(n + 1, 0);
        int j = 0, m = offers.size();
        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i - 1];
            while (j < m && offers[j][1] == i - 1) {
                dp[i] = max(dp[i], offers[j][2] + dp[offers[j][0]]);
                j++;
            }
        }
        return dp[n];
    }
};

