class Solution:
    def maximizeTheProfit(self, n: int, offers: List[List[int]]) -> int:
        import bisect
        offers.sort(key=lambda o: o[1])
        ends = [o[1] for o in offers]
        dp = [0] * (len(offers) + 1)
        for i, (s, e, g) in enumerate(offers, 1):
            t = bisect.bisect_left(ends, s)
            dp[i] = max(dp[i - 1], g + dp[t])
        return dp[len(offers)]

