class Solution {
    public int maximizeTheProfit(int n, int[][] offers) {
        java.util.Arrays.sort(offers, (a, b) -> a[1] - b[1]);
        int m = offers.length;
        int[] ends = new int[m];
        for (int i = 0; i < m; i++) ends[i] = offers[i][1];
        int[] dp = new int[m + 1];
        for (int i = 1; i <= m; i++) {
            int s = offers[i - 1][0], g = offers[i - 1][2];
            int t = java.util.Arrays.binarySearch(ends, s);
            if (t < 0) t = -(t + 1); else while (t > 0 && ends[t - 1] == s) t--;
            dp[i] = Math.max(dp[i - 1], g + dp[t]);
        }
        return dp[m];
    }
}

