var maximizeTheProfit = function(n, offers) {
    offers.sort((a, b) => a[1] - b[1]);
    const ends = offers.map(o => o[1]);
    const dp = Array(offers.length + 1).fill(0);
    const lowerBound = (arr, x) => { let lo = 0, hi = arr.length; while (lo < hi) { const mid = (lo + hi) >> 1; if (arr[mid] < x) lo = mid + 1; else hi = mid; } return lo; };
    for (let i = 1; i <= offers.length; i++) {
        const [s, , g] = offers[i - 1];
        dp[i] = Math.max(dp[i - 1], g + dp[lowerBound(ends, s)]);
    }
    return dp[offers.length];
};
